from jsonb_to_recordset('[{"id":"W1-M1","week_number":1,"step":"Meaning","target":"Main","payload":{"id":"W1-M1","step":"Meaning","target":"Main","prompt":"\"I had never lived abroad before.\" Had the speaker lived abroad before moving to Bristol?","options":["Yes","No"],"key":"No","accepted":[],"reason":"The past perfect describes the situation before the move."},"sort_order":1},{"id":"W1-M2","week_number":1,"step":"Meaning","target":"Main","payload":{"id":"W1-M2","step":"Meaning","target":"Main","prompt":"\"While I was waiting for the bus, I started chatting.\" Which action was in the background?","options":["waiting","chatting"],"key":"waiting","accepted":[],"reason":"The past continuous sets the scene; the past simple is the event."},"sort_order":2},{"id":"W1-M3","week_number":1,"step":"Meaning","target":"Main","payload":{"id":"W1-M3","step":"Meaning","target":"Main","prompt":"\"I have lived here for three years.\" Does the speaker still live in Bristol?","options":["Yes","No"],"key":"Yes","accepted":[],"reason":"The present perfect connects the past to now."},"sort_order":3},{"id":"W1-C1","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C1","step":"Choose","target":"Main","prompt":"I ___ to Bristol three years ago.","options":["moved","have moved"],"key":"moved","accepted":[],"reason":"\"Three years ago\" is a finished time."},"sort_order":4},{"id":"W1-C2","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C2","step":"Choose","target":"Main","prompt":"I ___ a lot of new friends since then.","options":["made","have made"],"key":"have made","accepted":[],"reason":"\"Since then\" means up to now."},"sort_order":5},{"id":"W1-C3","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C3","step":"Choose","target":"Main","prompt":"When I arrived at the station, the train ___.","options":["left","had left"],"key":"had left","accepted":[],"reason":"It left before I arrived."},"sort_order":6},{"id":"W1-C4","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C4","step":"Choose","target":"Main","prompt":"I ___ dinner when my phone rang.","options":["was cooking","cooked"],"key":"was cooking","accepted":[],"reason":"A longer action interrupted by a short one."},"sort_order":7},{"id":"W1-C5","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C5","step":"Choose","target":"Main","prompt":"___ you ever ___ in another country?","options":["Did ... live","Have ... lived"],"key":["Have","lived"],"accepted":[[],[]],"reason":"\"Ever\" asks about life experience up to now."},"sort_order":8},{"id":"W1-C6","week_number":1,"step":"Choose","target":"Main","payload":{"id":"W1-C6","step":"Choose","target":"Main","prompt":"She ___ her job last month and is now looking for a new one.","options":["has left","left"],"key":"left","accepted":[],"reason":"\"Last month\" is a finished time."},"sort_order":9},{"id":"W1-G1","week_number":1,"step":"Complete","target":"Main","payload":{"id":"W1-G1","step":"Complete","target":"Main","prompt":"While we ___ (drive) to the coast, it started to rain.","options":[],"key":"were driving","accepted":[],"reason":"Background action."},"sort_order":10},{"id":"W1-G2","week_number":1,"step":"Complete","target":"Main","payload":{"id":"W1-G2","step":"Complete","target":"Main","prompt":"By the time I got to the party, most people ___ (go) home.","options":[],"key":"had gone","accepted":[],"reason":"They left before I arrived."},"sort_order":11},{"id":"W1-G3","week_number":1,"step":"Complete","target":"Main","payload":{"id":"W1-G3","step":"Complete","target":"Main","prompt":"I ___ (know) Maria since we were at school.","options":[],"key":"have known","accepted":[],"reason":"Up to now with \"since\"; know is not used in the continuous."},"sort_order":12},{"id":"W1-G4","week_number":1,"step":"Complete","target":"Main","payload":{"id":"W1-G4","step":"Complete","target":"Main","prompt":"Last summer I ___ (spend) two weeks in Scotland.","options":[],"key":"spent","accepted":[],"reason":"Finished time."},"sort_order":13},{"id":"W1-G5","week_number":1,"step":"Complete","target":"Main","payload":{"id":"W1-G5","step":"Complete","target":"Main","prompt":"She was tired because she ___ (not sleep) the night before.","options":[],"key":"hadn''t slept","accepted":["had not slept"],"reason":"Earlier than the moment she was tired."},"sort_order":14},{"id":"W1-F1","week_number":1,"step":"Fix","target":"Main","payload":{"id":"W1-F1","step":"Fix","target":"Main","prompt":"I have moved to Leeds in 2023.","options":[],"key":"I moved to Leeds in 2023.","accepted":[],"reason":"\"In 2023\" is a finished time, so use the past simple."},"sort_order":15},{"id":"W1-F2","week_number":1,"step":"Fix","target":"Main","payload":{"id":"W1-F2","step":"Fix","target":"Main","prompt":"When I got home, my flatmate already cooked dinner.","options":[],"key":"When I got home, my flatmate had already cooked dinner.","accepted":[],"reason":"Cooking happened before I got home."},"sort_order":16},{"id":"W1-F3","week_number":1,"step":"Fix","target":"Main","payload":{"id":"W1-F3","step":"Fix","target":"Main","prompt":"I was knowing her for years before we worked together.","options":[],"key":"I had known her for years before we worked together.","accepted":[],"reason":"Know is a state verb, and this happened before the other past event."},"sort_order":17},{"id":"W1-R1","week_number":1,"step":"Rewrite","target":"Main","payload":{"id":"W1-R1","step":"Rewrite","target":"Main","prompt":"I started learning English in 2020. I''m still learning it. (since)","options":[],"key":"I''ve been learning English since 2020.","accepted":["I have been learning English since 2020."],"reason":"An activity that continues up to now."},"sort_order":18},{"id":"W1-R2","week_number":1,"step":"Rewrite","target":"Main","payload":{"id":"W1-R2","step":"Rewrite","target":"Main","prompt":"First the film started. Then we arrived. (When ... already)","options":[],"key":"When we arrived, the film had already started.","accepted":["The film had already started when we arrived."],"reason":"The past perfect shows which happened first."},"sort_order":19},{"id":"W1-R3","week_number":1,"step":"Rewrite","target":"Main","payload":{"id":"W1-R3","step":"Rewrite","target":"Main","prompt":"I was walking home. I saw an accident. (While)","options":[],"key":"While I was walking home, I saw an accident.","accepted":["I saw an accident while I was walking home."],"reason":"Background plus event."},"sort_order":20},{"id":"W1-L1","week_number":1,"step":"Light","target":"Light","payload":{"id":"W1-L1","step":"Light","target":"Light","prompt":"When I was a child, we ___ in a small flat.","options":["used to live","would live"],"key":"used to live","accepted":[],"reason":"Live is a state, so would is not possible."},"sort_order":21},{"id":"W1-L2","week_number":1,"step":"Light","target":"Light","payload":{"id":"W1-L2","step":"Light","target":"Light","prompt":"Every summer, my grandfather ___ us fishing.","options":["would take","has taken"],"key":"would take","accepted":["used to take"],"reason":"A repeated action in the past."},"sort_order":22},{"id":"W1-L3","week_number":1,"step":"Light","target":"Light","payload":{"id":"W1-L3","step":"Light","target":"Light","prompt":"I''m tired because I ___ all morning.","options":["''ve been studying","study"],"key":"''ve been studying","accepted":[],"reason":"An activity up to now with a result you can see."},"sort_order":23},{"id":"W1-U1","week_number":1,"step":"Use it","target":"Main","payload":{"id":"W1-U1","step":"Use it","target":"Main","prompt":"Tell me about something you used to do as a child that you don''t do now.","options":[],"key":"Any correct sentence with used to or would","accepted":[],"reason":"AI checks the form and gives one correction."},"sort_order":24},{"id":"W1-U2","week_number":1,"step":"Use it","target":"Main","payload":{"id":"W1-U2","step":"Use it","target":"Main","prompt":"What has changed in your life since you started your current job or studies?","options":[],"key":"Any correct sentence with the present perfect and since","accepted":[],"reason":"AI checks the form and gives one correction."},"sort_order":25},{"id":"W1-V1","week_number":1,"step":"Review (clinic)","target":"Review","payload":{"id":"W1-V1","step":"Review (clinic)","target":"Review","prompt":"I usually ___ to work, but this week I''m working from home.","options":["walk","am walking"],"key":"walk","accepted":[],"reason":"A usual habit uses the present simple."},"sort_order":26},{"id":"W1-V2","week_number":1,"step":"Review (clinic)","target":"Review","payload":{"id":"W1-V2","step":"Review (clinic)","target":"Review","prompt":"She''s ___ engineer.","options":["a","an"],"key":"an","accepted":[],"reason":"Use an before a vowel sound."},"sort_order":27},{"id":"W1-E1","week_number":1,"step":"Extra","target":"Extra","payload":{"id":"W1-E1","step":"Extra","target":"Extra","prompt":"We ___ (watch) TV when the lights went out.","options":[],"key":"were watching","accepted":[],"reason":"Background action interrupted."},"sort_order":28},{"id":"W1-E2","week_number":1,"step":"Extra","target":"Extra","payload":{"id":"W1-E2","step":"Extra","target":"Extra","prompt":"I ___ (never / see) snow until I moved to Canada.","options":[],"key":"had never seen","accepted":[],"reason":"Before another past event."},"sort_order":29},{"id":"W1-E3","week_number":1,"step":"Extra","target":"Extra","payload":{"id":"W1-E3","step":"Extra","target":"Extra","prompt":"She ___ (work) here since 2019.","options":[],"key":"has worked","accepted":["has been working"],"reason":"Up to now with \"since\"; both forms are correct."},"sort_order":30},{"id":"W2-M1","week_number":2,"step":"Meaning","target":"Main","payload":{"id":"W2-M1","step":"Meaning","target":"Main","prompt":"\"I''m meeting a careers adviser on Tuesday.\" Is this an arrangement already made, or a decision made now?","options":["arrangement","decision now"],"key":"arrangement","accepted":[],"reason":"The present continuous is used for fixed arrangements."},"sort_order":1},{"id":"W2-M2","week_number":2,"step":"Meaning","target":"Main","payload":{"id":"W2-M2","step":"Meaning","target":"Main","prompt":"\"When I finish it, I''ll apply.\" Is finishing the course in the present or the future?","options":["present","future"],"key":"future","accepted":[],"reason":"After when, use the present simple for the future."},"sort_order":2},{"id":"W2-M3","week_number":2,"step":"Meaning","target":"Main","payload":{"id":"W2-M3","step":"Meaning","target":"Main","prompt":"\"If I had more time, I''d study full-time.\" Does the speaker have more time?","options":["Yes","No"],"key":"No","accepted":[],"reason":"The second conditional describes an imagined situation."},"sort_order":3},{"id":"W2-C1","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C1","step":"Choose","target":"Main","prompt":"Look at those clouds! It ___ rain.","options":["''s going to","''s raining"],"key":"''s going to","accepted":[],"reason":"A prediction based on what you can see now."},"sort_order":4},{"id":"W2-C2","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C2","step":"Choose","target":"Main","prompt":"I ___ lunch with my sister tomorrow. We''ve booked a table.","options":["''m having","have"],"key":"''m having","accepted":[],"reason":"A fixed arrangement."},"sort_order":5},{"id":"W2-C3","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C3","step":"Choose","target":"Main","prompt":"My flight ___ at 6 a.m., so I need to leave home at 4.","options":["leaves","is leave"],"key":"leaves","accepted":[],"reason":"Timetables use the present simple."},"sort_order":6},{"id":"W2-C4","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C4","step":"Choose","target":"Main","prompt":"A: I''ve left my wallet at home. B: Don''t worry, I ___ for the coffees.","options":["''ll pay","pay"],"key":"''ll pay","accepted":[],"reason":"An offer or decision made while speaking."},"sort_order":7},{"id":"W2-C5","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C5","step":"Choose","target":"Main","prompt":"I''ll call you as soon as I ___ home.","options":["get","will get"],"key":"get","accepted":[],"reason":"After as soon as, use the present simple for the future."},"sort_order":8},{"id":"W2-C6","week_number":2,"step":"Choose","target":"Main","payload":{"id":"W2-C6","step":"Choose","target":"Main","prompt":"I ___ start my own business one day. That''s my plan.","options":["''m going to","''m starting"],"key":"''m going to","accepted":[],"reason":"An intention with no fixed arrangement yet."},"sort_order":9},{"id":"W2-G1","week_number":2,"step":"Complete","target":"Main","payload":{"id":"W2-G1","step":"Complete","target":"Main","prompt":"We ___ (move) to Valencia next month. We''ve already signed the contract.","options":[],"key":"''re moving","accepted":["are moving"],"reason":"A fixed arrangement."},"sort_order":10},{"id":"W2-G2","week_number":2,"step":"Complete","target":"Main","payload":{"id":"W2-G2","step":"Complete","target":"Main","prompt":"I''m sure you ___ (enjoy) the course.","options":[],"key":"''ll enjoy","accepted":["will enjoy"],"reason":"A prediction based on opinion."},"sort_order":11},{"id":"W2-G3","week_number":2,"step":"Complete","target":"Main","payload":{"id":"W2-G3","step":"Complete","target":"Main","prompt":"Before I ___ (start) my new job, I''m going to take a holiday.","options":[],"key":"start","accepted":[],"reason":"After before, use the present simple for the future."},"sort_order":12},{"id":"W2-G4","week_number":2,"step":"Complete","target":"Main","payload":{"id":"W2-G4","step":"Complete","target":"Main","prompt":"I ___ (not / come) to the meeting on Friday. I''ve got a dentist''s appointment.","options":[],"key":"''m not coming","accepted":["am not coming"],"reason":"A fixed arrangement."},"sort_order":13},{"id":"W2-G5","week_number":2,"step":"Complete","target":"Main","payload":{"id":"W2-G5","step":"Complete","target":"Main","prompt":"Wait, I ___ (help) you carry that.","options":[],"key":"''ll help","accepted":["will help"],"reason":"An offer made while speaking."},"sort_order":14},{"id":"W2-F1","week_number":2,"step":"Fix","target":"Main","payload":{"id":"W2-F1","step":"Fix","target":"Main","prompt":"I''ll tell you when I will know the results.","options":[],"key":"I''ll tell you when I know the results.","accepted":[],"reason":"After when, use the present simple for the future."},"sort_order":15},{"id":"W2-F2","week_number":2,"step":"Fix","target":"Main","payload":{"id":"W2-F2","step":"Fix","target":"Main","prompt":"I can''t come on Saturday. I will visit my parents. We arranged it last week.","options":[],"key":"I''m visiting my parents.","accepted":[],"reason":"It was arranged, so use the present continuous."},"sort_order":16},{"id":"W2-F3","week_number":2,"step":"Fix","target":"Main","payload":{"id":"W2-F3","step":"Fix","target":"Main","prompt":"We''re go to the cinema tonight.","options":[],"key":"We''re going to the cinema tonight.","accepted":[],"reason":"The present continuous needs the -ing form."},"sort_order":17},{"id":"W2-R1","week_number":2,"step":"Rewrite","target":"Main","payload":{"id":"W2-R1","step":"Rewrite","target":"Main","prompt":"My plan: find a new flat. (going to)","options":[],"key":"I''m going to find a new flat.","accepted":[],"reason":"An intention."},"sort_order":18},{"id":"W2-R2","week_number":2,"step":"Rewrite","target":"Main","payload":{"id":"W2-R2","step":"Rewrite","target":"Main","prompt":"Finish work, then phone you. (as soon as)","options":[],"key":"I''ll phone you as soon as I finish work.","accepted":["As soon as I finish work, I''ll phone you."],"reason":"Will in the main clause, present simple after as soon as."},"sort_order":19},{"id":"W2-R3","week_number":2,"step":"Rewrite","target":"Main","payload":{"id":"W2-R3","step":"Rewrite","target":"Main","prompt":"Meeting with Ana, Thursda