resent passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses.","sort_order":17},{"id":"CP1-18","week_number":4,"reserve":false,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive.","sort_order":18},{"id":"CP1-19","week_number":4,"reserve":false,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it.","sort_order":19},{"id":"CP1-20","week_number":4,"reserve":false,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause.","sort_order":20},{"id":"CP1-R1","week_number":1,"reserve":true,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since.","sort_order":1},{"id":"CP1-R2","week_number":2,"reserve":true,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before.","sort_order":2},{"id":"CP1-R3","week_number":3,"reserve":true,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary.","sort_order":3},{"id":"CP1-R4","week_number":4,"reserve":true,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by.","sort_order":4}]'::jsonb) as v(
